for k in K:
 m.addCons(quicksum(x[k,START,i] for i in I)==1);m.addCons(quicksum(x[k,i,END] for i in I)==1)
 for i in I:
  inc=quicksum(x[k,a,i] for a in [START,*I] if (a,i) in arcs);out=quicksum(x[k,i,b] for b in [*I,END] if (i,b) in arcs)
  m.addCons(inc==out);m.addCons(visit[k,i]==inc);m.addCons(p[k,i]<=C*direction[k,i]);m.addCons(q[k,i]<=C*(visit[k,i]-direction[k,i]));m.addCons(direction[k,i]<=visit[k,i]);m.addCons(order[k,i]<=n*visit[k,i])
  z=x[k,START,i]; e=L[k,i]-LS[k]-p[k,i]+q[k,i];m.addCons(e<=C*(1-z));m.addCons(e>=-C*(1-z));z=x[k,i,END];e=LE[k]-L[k,i];m.addCons(e<=C*(1-z));m.addCons(e>=-C*(1-z))
  for j in I:
   if i!=j:
