for i,s in enumerate(S):
 P=quicksum(p[k,i] for k in K);Q=quicksum(q[k,i] for k in K);t=s['net_rebalancing_target'];m.addCons(P<=s['initial_bikes']);m.addCons(s['initial_bikes']-P+Q<=s['station_capacity']);m.addCons(t-(P-Q)<=u[i]);m.addCons((P-Q)-t<=u[i])
m.setObjective(quicksum(dist[a,b]*x[k,a,b] for k in K for a,b in arcs)+D['penalty_weight']*quicksum(u.values()),'minimize');m.optimize();assert m.getNSols()>0,str(m.getStatus())
